// Special credit https://www.youtube.com/watch?v=QAOt24qV98c&ab_channel=FencerDevLog

float SPEED = 1.0;
vec2 GRID = vec2(12.0, 6.0);


float hash11(float n)
{
    return fract(sin(n) * 43758.5453123);
}

float hash2(vec2 p)  // replace this by something better
{
    p  = 50.0*fract( p*0.3183099 + vec2(0.71,0.113));
    return -1.0+2.0*fract( p.x*p.y*(p.x+p.y) );
}

vec2 drop_layer(vec2 uv, float time)
{
    vec2 grid = GRID;
    float noise = (texture(iChannel0,uv).r * 2.0 - 1.0) * 0.5;       
    float fall = (hash11(floor(uv*grid).x + 1.0) * 0.1);
    uv.y += fall * time;
    vec2 drop_uv = fract(uv*grid + vec2(noise*0.5,noise*0.1));
    drop_uv = 2.0 * drop_uv - 1.0;
    vec2 drop_size = drop_uv / grid;
    float drop_shape = smoothstep(0.03,0.02,length(drop_size));
    return drop_size * drop_shape;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    uv.x *= iResolution.x / iResolution.y; // ratio

    float time = iTime * SPEED;
    vec2 drops = drop_layer(uv, time);
    drops += drop_layer(uv * 2.0, time * 1.5);
    drops += drop_layer(uv * 4.0, time * 2.0);

    // Time varying pixel color
    vec3 col = texture(iChannel1, uv + drops).rgb;

    // Output to screen
    fragColor = vec4(col,1.0);
}
